let guildBondPartner='';
function socialView(){if(developerMode)return '<div class="empty"><h1>Your guild uses your normal account</h1><p>Exit Developer Lab to contribute coins and adventure with your partner.</p></div>';
 if(!social.joined)return `<div class="page-head"><div><div class="eyebrow">A home between adventures</div><h1>The Guild Hall</h1><p>Found a private guild for up to eight members. Make a home and memories together.</p></div></div><div class="social-forms"><form id="guild-create"><h2>Start your guild</h2><label>Guild name<input name="name" required minlength="3" maxlength="28" placeholder="e.g. Willow Watch"></label><button class="primary" ${busy?'disabled':''}>Create guild · Free</button></form><form id="guild-join"><h2>Join a guild</h2><label>Invite code<input name="code" required minlength="8" maxlength="8" placeholder="8-character invite"></label><button ${busy?'disabled':''}>Join guild</button></form></div><p class="hint">Use a normal character in town. A guild holds eight accounts. Dungeon parties still hold two. House purchases use contributed guild coins, never another player’s wallet directly.</p>`;
 const bonds=social.bonds||[],selectedBond=bonds.find(b=>b.partner===guildBondPartner)||bonds[0]||social.bond;const g={...social,bond:selectedBond},emblems={leaf:'❧',moon:'☾',sun:'☀',sword:'⚔'},clears=g.bond.clears||0;
 return `<div class="page-head"><div><div class="eyebrow">${g.members.map(h).join(' & ')}</div><h1>${emblems[g.emblem]} ${h(g.name)}</h1><p>${g.members.length} / ${g.capacity||8} members · All members can decorate and improve your shared home.</p></div><button data-refresh-social>Refresh</button></div>${houseArt()}<section class="social-card"><h2>Shared guild projects</h2><p>Build useful rooms together using your guild treasury and adventure supplies.</p><div class="build-grid">${(g.projects||[]).map(p=>`<article class="skill-card"><h3>${h(p.name)}</h3><p>${h(p.benefit)}</p><p>${p.coins} coins · ${p.supplies} supplies · House stage 1</p>${socialButton(g.owned.includes('project:'+p.id)?'Completed':'Build room','project',p.id,g.owned.includes('project:'+p.id)||g.upgrade<1||g.coins<p.coins||g.materials<p.supplies)}</article>`).join('')}</div></section><div class="social-columns"><section class="social-card"><h2>Make yourselves at home</h2><p><strong>${g.coins} guild coins · ${g.materials} adventure supplies</strong></p><p>Contribute from your character in town. Completing a credited dungeon together delivers supplies.</p><div class="social-actions">${[10,25,50].map(n=>socialButton('Contribute '+n,'donate',String(n),game.player.coins<n||game.mode!=='TOWN')).join('')}</div>${g.upgrade<3?socialButton(`Improve house · ${[50,100,180][g.upgrade]} coins + ${[0,2,4][g.upgrade]} supplies`,'upgrade','',g.coins<[50,100,180][g.upgrade]||g.materials<[0,2,4][g.upgrade]):'<p>All three house improvements complete.</p>'}<details><summary>Guild settings & invite</summary>${g.owner&&g.members.length>1?`<form id="guild-transfer"><label>Transfer leadership to<select name="member">${g.members.filter(m=>m!==user).map(m=>`<option value="${h(m)}">${h(m)}</option>`).join('')}</select></label><label><input type="checkbox" required> I understand they will control guild invitations and leadership.</label><button type="submit" ${busy?'disabled':''}>Transfer leadership</button></form>`:''}<p>${g.members.map(h).join(' · ')}</p>${g.owner&&g.members.length<(g.capacity||8)?`<code class="party-code">${h(g.invite)}</code><button data-copy-guild>Copy invite</button>${socialButton('Renew invite','invite')}`:''}<div class="social-actions">${Object.entries(emblems).map(([id,symbol])=>socialButton(symbol,'emblem',id)).join('')}</div>${socialLeaving?`<p>Leave this guild? Contributions stay in its house. Transfer leadership before leaving; an empty guild is retired.</p>${socialButton('Confirm leave','leave')}<button data-cancel-social-leave>Stay</button>`:'<button data-social-leave>Leave guild</button>'}</details></section><section class="social-card"><h2>Your bonds</h2>${bonds.length?`<label>Adventuring partner <select id="guild-bond-partner">${bonds.map(b=>`<option value="${h(b.partner)}" ${b.partner===selectedBond.partner?'selected':''}>${h(b.partner)}</option>`).join('')}</select></label>`:''}<p>${g.members.length<2?'Invite your partner to begin.':clears+' credited adventures with '+h(selectedBond.partner||'your partner')}</p><ul class="bond-milestones">${[[1,'Trail Companions','Shared title'],[3,'In Step','Rally: once per run, +10% health and +6 resource to both'],[5,'Homeward Bound','Twin lantern decoration']].map(([n,title,detail])=>`<li>${clears>=n?'✓':'◇'} <strong>${title}</strong> · ${n} clears<small>${detail}</small></li>`).join('')}</ul><p class="small muted">At least three combat rounds per clear. One bond credit per five minutes. All victories still award normal loot and are recorded.</p></section></div><section class="social-card"><h2>Furnishings & trophies</h2><p>One decoration per wall, floor, hearth, shelf and garden slot. Replacing a decoration keeps it in your collection.</p><div class="decoration-grid">${g.catalog.map(d=>{const owned=g.owned.includes(d.id),placed=g.placed[d.slot]===d.id;return `<article><div class="eyebrow">${pretty(d.slot)}</div><h3>${h(d.name)}</h3><p>${owned?'In your collection':d.requirement==='warden'?'Defeat the Warden together':d.requirement==='bond'?'Earn five bond credits':d.requirement==='archive'?'Complete the Campaign archive project':d.price+' guild coins'}</p>${owned?socialButton(placed?'Placed':'Place','place',d.id,placed):socialButton(d.requirement?'Earn through adventures':'Buy','buy',d.id,!!d.requirement||g.coins<d.price)}</article>`;}).join('')}</div></section><div class="social-columns"><section class="social-card"><h2>Leave a little note</h2><div class="social-actions">${[['cheer','🎉 Cheers'],['thanks','♥ Thank you'],['ready','⚔ Ready'],['close','😅 Too close']].map(([id,label])=>socialButton(label,'react',id)).join('')}</div><div class="social-log">${[...g.guestbook].reverse().map(t=>`<p>${h(t)}</p>`).join('')||'<p>Your shared guestbook starts here.</p>'}</div></section><section class="social-card"><h2>Adventures remembered</h2><div class="social-log">${[...g.bond.memories].reverse().map(t=>`<p>${h(t)}</p>`).join('')||'<p>Complete a dungeon together to record your first memory.</p>'}</div><details><summary>House contributions & changes</summary><div class="social-log">${[...g.history].reverse().map(t=>`<p>${h(t)}</p>`).join('')}</div></details></section></div>`;
}
setInterval(async()=>{if(user&&!developerMode&&tab==='social'&&!busy&&social.joined&&document.visibilityState==='visible'){try{await loadSocial();render();}catch(e){notify(e.message,true);}}},10000);
let deleteSlot=null;
let slotScreen=false,slotList={slots:[],generation:0};
function renderSlots(){root.innerHTML=`<header class="topbar">${brand()}<button data-close-characters>Back</button></header><main class="game-main"><h1>Your characters</h1><p>Four slots, one per class. Items, coins and adventures stay separate. Guild and bond belong to your account. The leaderboard shows your active character.</p><div class="skill-grid">${slotList.slots.map(s=>`<article class="skill-card"><div class="eyebrow">Slot ${s.slot+1}${s.active?' · Active':''}</div><h2>${s.empty?'New character':h(s.name)}</h2><p>${s.empty?'Choose a class after opening this slot.':pretty(s.type)+' · Level '+s.level}</p><button data-select-slot="${s.slot}" ${busy?'disabled':''}>${s.active?'Continue':s.empty?'Create character':'Play character'}</button>${!s.empty?deleteSlot===s.slot?`<div class="sale-confirm"><p>Permanently delete <strong>${h(s.name)}</strong>, level ${s.level} ${pretty(s.type)}? Equipment, coins and story progress for this character will be lost. This cannot be undone. Your login, other characters, guild and bonds stay.</p><button class="danger" data-confirm-delete-slot="${s.slot}" ${busy?'disabled':''}>Permanently delete character</button><button data-cancel-delete-slot ${busy?'disabled':''}>Keep character</button></div>`:`<button class="quiet danger" data-delete-slot="${s.slot}" ${busy?'disabled':''}>Delete save</button>`:''}</article>`).join('')}</div><p class="hint">Leave your co-op party before switching. Existing solo expeditions resume where you left them.</p></main>`;}
function render(){const packScroll=tab==='pack'?window.scrollY:null,bulkOpen=!!root.querySelector('.bulk-panel[open]'),storyOpen=!!root.querySelector('.story-fold[open]');if(!user){renderAuth();return;}if(slotScreen){renderSlots();return;}if(game?.needsCharacter){renderCreation();return;}if(!game)return;
 const main=tab==='social'?socialView():tab==='coop'?coopView():tab==='leaderboard'?leaderboard():tab==='pack'?pack():tab==='journal'?journal():tab==='skills'?skills():game.mode==='TOWN'?town():expedition();
 root.innerHTML=`<header class="topbar">${brand()}<div class="top-right">${!developerMode?'<button data-characters>Characters</button>':''}<span class="saved" role="status">${busy?'Saving…':'Saved'}</span>${developerEnabled?`<button data-lab>${developerMode?'Exit developer lab':'Developer lab'}</button>`:''}<button class="quiet small" data-logout ${busy?'disabled':''}>Sign out</button></div></header><div class="game-shell">${developerMode?developerToolbar():''}${statusBar()}${navigation()}<main class="game-main" id="main-content">${['social','coop'].includes(tab)?`<div class="location-return"><button data-tab="journey">← Kingdom map</button><span>${tab==='social'?'Cindergard · Guild Hall':'Cindergard · Dungeon Lodge'}</span></div>`:''}${!developerMode&&game.coopActive&&tab!=='coop'?'<section class="party-return" role="status"><strong>Your co-op party is active</strong><p>Solo actions pause while you are together. Continue your mission, or leave the party from the Dungeon Lodge.</p><button class="primary" data-tab="coop">Return to your party →</button></section>':''}${main}</main></div>`;
 if(storyOpen&&root.querySelector('.story-fold'))root.querySelector('.story-fold').open=true;
 if(packScroll!==null){const panel=root.querySelector('.bulk-panel');if(panel)panel.open=bulkOpen;window.scrollTo(0,packScroll);}
}
root.addEventListener('click',async event=>{
 const button=event.target.closest('button');if(!button||button.disabled)return;
 if(button.dataset.forgeFilter){forgeFilter=button.dataset.forgeFilter;render();return;}
 if(button.hasAttribute('data-open-forge')){if(game.mode!=='TOWN'){notify('Return to the Crown District to use the Forge.');return;}tab='journey';townScreen='town';townPlace='forge';render();return;}
 if(button.hasAttribute('data-reload')){start();return;}
 if(button.hasAttribute('data-characters')){deleteSlot=null;slotList=await api('/api/characters');slotScreen=true;render();return;}
 if(button.hasAttribute('data-close-characters')){slotScreen=false;game=await api('/api/game');render();return;}
 if(button.hasAttribute('data-delete-slot')&&!busy){deleteSlot=Number(button.dataset.deleteSlot);render();return;}
 if(button.hasAttribute('data-cancel-delete-slot')&&!busy){deleteSlot=null;render();return;}
 if(button.hasAttribute('data-confirm-delete-slot')&&!busy){busy=true;render();try{slotList=await api('/api/characters/delete',{slot:Number(button.dataset.confirmDeleteSlot),generation:slotList.generation,confirmed:true});game=await api('/api/game');deleteSlot=null;selectedItem=null;bulkIds.clear();notify('Character deleted. The slot is ready for a new character.');}catch(e){deleteSlot=null;notify(e.message,true);slotList=await api('/api/characters');}finally{busy=false;render();}return;}
 if(button.hasAttribute('data-select-slot')&&!busy){busy=true;try{game=await api('/api/characters/select',{slot:Number(button.dataset.selectSlot),generation:slotList.generation});slotScreen=false;tab='journey';bulkIds.clear();}catch(e){notify(e.message,true);slotList=await api('/api/characters');}finally{busy=false;render();}return;}
 if(button.dataset.auth){authMode=button.dataset.auth;renderAuth();return;}
 if(button.dataset.class){selectedClass=button.dataset.class;document.querySelectorAll('[data-class]').forEach(b=>{b.classList.toggle('selected',b.dataset.class===selectedClass);b.setAttribute('aria-pressed',String(b.dataset.class===selectedClass));});return;}
 if(button.hasAttribute('data-lab')){if(busy)return;const previous=developerMode;busy=true;try{developerMode=!developerMode;game=await api('/api/game');if(developerMode&&game.needsCharacter)game=await api('/api/character',{name:'Developer',playerClass:'MAGE'});tab='journey';}catch(e){developerMode=previous;game=await api('/api/game');notify(e.message,true);}finally{busy=false;render();}return;}
 if(button.hasAttribute('data-ask-coop-leave')){coopLeaving=true;render();return;}
 if(button.hasAttribute('data-cancel-coop-leave')){coopLeaving=false;render();return;}
 if(button.hasAttribute('data-copy-guild')){try{await navigator.clipboard.writeText(social.invite);notify('Guild invite copied.');}catch{notify('Select the displayed invite to copy it.');}return;}
 if(button.hasAttribute('data-social-leave')){socialLeaving=true;render();return;}
 if(button.hasAttribute('data-cancel-social-leave')){socialLeaving=false;render();return;}
 if(button.hasAttribute('data-refresh-social')){await loadSocial();render();return;}
 if(button.dataset.social&&!busy){busy=true;try{social=await api('/api/social',{version:social.version,action:button.dataset.social,value:button.dataset.value});game=await api('/api/game');socialLeaving=false;}catch(e){notify(e.message,true);await loadSocial();}finally{busy=false;render();}return;}
 if(button.dataset.coop&&!busy){busy=true;try{party=await api(button.dataset.coop==='create'?'/api/coop/create':'/api/coop/move',button.dataset.coop==='create'?(button.dataset.choice.startsWith('dungeon:')?{dungeon:button.dataset.choice.slice(8)}:button.dataset.choice!==''?{route:Number(button.dataset.choice)}:{}):{id:party.id,round:party.round,action:button.dataset.coop,value:button.dataset.choice});partyFetchedAt=Date.now();coopLeaving=false;game.coopActive=!!party.joined&&['LOBBY','BATTLE','RESCUE'].includes(party.state);if(!game.coopActive)game=await api('/api/game');if(!party.joined){tab='journey';}}catch(e){notify(e.message,true);await loadParty();}finally{busy=false;render();}return;}
 if(button.hasAttribute('data-copy-party')){try{await navigator.clipboard.writeText(party.id.toUpperCase());notify('Party code copied.');}catch{notify('Select the displayed code to copy it.');}return;}
 if(button.hasAttribute('data-bulk-common')||button.hasAttribute('data-bulk-rare')){bulkIds=new Set(game.inventory.filter(r=>!r.equipped&&!r.protected&&r.item.rarity===(button.hasAttribute('data-bulk-rare')?'RARE':'COMMON')).map(r=>r.item.id));bulkConfirm=false;render();root.querySelector('.bulk-panel').open=true;return;}
 if(button.hasAttribute('data-bulk-clear')){bulkIds.clear();bulkConfirm=false;render();root.querySelector('.bulk-panel').open=true;return;}
 if(button.hasAttribute('data-bulk-review')||button.hasAttribute('data-bulk-cancel')){bulkConfirm=button.hasAttribute('data-bulk-review');render();root.querySelector('.bulk-panel').open=true;return;}
 if(button.dataset.gathering){gatheringSite=button.dataset.gathering;townScreen='gathering';render();return;}
 if(button.dataset.region){townScreen='world';kingdomRegion=button.dataset.region;render();return;}
 if(button.dataset.townPlace){townPlace=button.dataset.townPlace;render();return;}
 if(button.dataset.townScreen){townScreen=button.dataset.townScreen;render();return;}
 if(button.dataset.packFilter){packFilter=button.dataset.packFilter;sellConfirm=null;render();return;}
 if(button.dataset.item||button.dataset.slotItem){selectedItem=button.dataset.item||button.dataset.slotItem;if(button.dataset.slotItem)packFilter='ALL';sellConfirm=null;render();return;}
 if(button.dataset.sellItem){sellConfirm=button.dataset.sellItem;render();return;}
 if(button.hasAttribute('data-cancel-sale')){sellConfirm=null;render();return;}
 if(button.dataset.tab){if(busy)return;tab=button.dataset.tab;if(tab==='journey'){try{game=await api('/api/game');}catch(e){notify(e.message,true);}}if(tab==='social'&&!developerMode){try{await loadSocial();}catch(e){notify(e.message,true);}}if(tab==='leaderboard')await loadLeaders();if(tab==='coop'&&!developerMode){try{await loadParty();}catch(e){notify(e.message,true);}}render();return;}
 if(button.hasAttribute('data-logout')){try{await api('/api/logout',{});user=null;game=null;developerMode=false;developerEnabled=false;social={joined:false};party={joined:false};tab='journey';await token();render();}catch(e){notify(e.message,true);}return;}
 if(button.dataset.action&&!busy){const beforeIds=new Set(game.inventory.map(r=>r.item.id));const beforeCombat=game.mode==='COMBAT'?{health:game.player.health,resource:game.player.resource,enemy:game.enemy.health}:null;let chestReward=null;busy=true;render();try{game=await api('/api/command',{version:game.version,action:button.dataset.action,value:button.dataset.value});if(beforeCombat){const lines=[],health=game.player.health-beforeCombat.health,resource=game.player.resource-beforeCombat.resource,damage=game.enemy?beforeCombat.enemy-game.enemy.health:['TRAIL','OBJECTIVE','COMPLETE'].includes(game.mode)?beforeCombat.enemy:0;if(damage>0)lines.push(damage+' enemy health lost');if(health)lines.push((health>0?'+':'')+health+' health');if(resource)lines.push((resource>0?'+':'')+resource+' resource');lastCombatFeedback={lines:lines.length?lines:['Turn resolved'],damage,health,action:button.dataset.value};}else lastCombatFeedback=null;sellConfirm=null;bulkConfirm=false;bulkIds.clear();if(button.dataset.action==='craft'){const crafted=game.inventory.find(r=>!beforeIds.has(r.item.id));if(crafted){selectedItem=crafted.item.id;packFilter='ALL';tab='pack';notify('Crafted '+crafted.item.name+'. Select Equip item to use it.');}else notify('Crafted two field potions.');}if(button.dataset.action==='open_chest')chestReward=game.inventory.find(r=>!beforeIds.has(r.item.id))?.item;}catch(e){notify(e.message,true);if(e.status===409)game=await api('/api/game');}finally{busy=false;render();if(beforeCombat)playCombatImpact();if(chestReward)revealChest(chestReward);}}
});
root.addEventListener('submit',async event=>{
 event.preventDefault();if(busy)return;const data=new FormData(event.target);busy=true;
 const submit=event.target.querySelector('button[type="submit"],button.primary');if(submit)submit.disabled=true;
 try{
  if(event.target.id==='build-loadout'){game=await api('/api/command',{version:game.version,action:'loadout',value:data.getAll('ability').join(',')});notify('Combat loadout saved.');}
  else if(event.target.id==='guild-transfer'){social=await api('/api/social',{version:social.version,action:'transfer',value:data.get('member')});notify('Guild leadership transferred.');}
  else if(event.target.id==='guild-create'||event.target.id==='guild-join'){social=await api('/api/social',{version:0,action:event.target.id==='guild-create'?'create':'join',value:data.get(event.target.id==='guild-create'?'name':'code')});}
  else if(event.target.id==='coop-join'){party=await api('/api/coop/join',{code:data.get('code')});partyFetchedAt=Date.now();game=await api('/api/game');}
  else if(event.target.id==='auth-form'){
   const credentials={username:data.get('username'),password:data.get('password')};
   if(authMode==='register')await api('/api/register',credentials);
   await api('/api/login',credentials,true);await token();const me=await api('/api/me');user=me.username;developerEnabled=(await api('/api/developer/me')).enabled;game=await api('/api/game');
  }else if(event.target.id==='character-form')game=await api('/api/character',{name:data.get('name'),playerClass:selectedClass});
  render();
 }catch(e){notify(e.message,true);}finally{busy=false;if(submit)submit.disabled=false;if(user&&game)render();}
});
start();

root.addEventListener('change',event=>{if(event.target.dataset.bulkId){if(event.target.checked)bulkIds.add(event.target.dataset.bulkId);else bulkIds.delete(event.target.dataset.bulkId);bulkConfirm=false;render();root.querySelector('.bulk-panel').open=true;}});
